export default async function plan({ projectId }, context) {
  if (!projectId || projectId.startsWith("YOUR_")) throw Error("Configure Todoist project");
  const messages = [];
  let token = null,
    seen = new Set();
  do {
    const r = await context.actions.call("gmail.fetch_emails", {
      query: "in:inbox {is:starred is:unread}",
      maxResults: 100,
      detail: "summary",
      ...(token ? { pageToken: token } : {}),
    });
    if (!Array.isArray(r.messages)) throw Error("Invalid Gmail list");
    messages.push(...r.messages);
    token = r.nextPageToken ?? null;
    if (token) {
      if (seen.has(token)) throw Error("Repeated Gmail page");
      seen.add(token);
    }
  } while (token);
  const tasks = [];
  let cursor = null;
  seen = new Set();
  do {
    const r = await context.actions.call("todoist.list_tasks", {
      projectId,
      limit: 200,
      ...(cursor ? { cursor } : {}),
    });
    if (!Array.isArray(r.tasks)) throw Error("Invalid Todoist list");
    tasks.push(...r.tasks);
    cursor = r.nextCursor ?? null;
    if (cursor) {
      if (seen.has(cursor)) throw Error("Repeated Todoist cursor");
      seen.add(cursor);
    }
  } while (cursor);
  const active = new Map(messages.map((m) => [m.messageId, m])),
    tracked = new Map();
  for (const t of tasks) {
    const match = /(?:^|\n)\[gmail-message:([a-zA-Z0-9_-]+)\]$/.exec(t.description ?? "");
    if (!match) continue;
    if (tracked.has(match[1])) throw Error("Duplicate Gmail task marker");
    tracked.set(match[1], t);
  }
  const work = [];
  for (const [id, m] of active) {
    if (!/^[a-zA-Z0-9_-]+$/.test(id)) throw Error("Invalid Gmail ID");
    if (!tracked.has(id))
      work.push({
        mode: "create",
        messageId: id,
        taskId: "",
        subject: m.subject || "(no subject)",
      });
    else if (m.labelIds?.includes("UNREAD"))
      work.push({ mode: "mark", messageId: id, taskId: "", subject: m.subject || "(no subject)" });
  }
  for (const [id, t] of tracked)
    if (!active.has(id))
      work.push({ mode: "close", messageId: id, taskId: t.id, subject: t.content });
  return { work };
}

