export default function next({ work, previous }) {
  const i = previous?.index ?? 0;
  if (i >= work.length)
    return {
      state: { index: i },
      more: false,
      mode: "done",
      messageId: "none",
      taskId: "none",
      subject: "none",
    };
  const x = work[i];
  return {
    state: { index: i + 1 },
    more: true,
    mode: x.mode,
    messageId: x.messageId || "none",
    taskId: x.taskId || "none",
    subject: x.subject || "(no subject)",
  };
}

