export default function format({ result, messageId }) {
  if (!result || !["description", "actions", "answer"].every((k) => typeof result[k] === "string"))
    throw Error("Invalid model result");
  return {
    description:
      result.description +
      "\n\nProposed actions\n" +
      result.actions +
      "\n\nProposed answer\n" +
      result.answer +
      "\n\n[gmail-message:" +
      messageId +
      "]",
  };
}

